_⚠️ Potential issue_ | _🟠 Major_

**Potential memory leak: window event listeners not cleaned up on unmount during drag.**

If the component unmounts while a drag is in progress, the `mousemove` and `mouseup` listeners attached to `window` won't be removed. The cleanup function only removes `mousedown` handlers from the drag handles.



<details>
<summary>🐛 Suggested fix to track and clean up window listeners</summary>

```diff
+  const windowListenersRef = useRef<{ cleanup: () => void } | null>(null);
+
   useEffect(() => {
     const onDrag = (e: MouseEvent) => {
       if (dragSide.current === 'both' || dragSide.current === 'right') {
         targetRef.current!.style.width = `${dragStart.current![0] + e.clientX}px`;
       }
       if (dragSide.current === 'both' || dragSide.current === 'bottom') {
         targetRef.current!.style.height = `${dragStart.current![1] + e.clientY}px`;
       }
     };

     const onEnd = () => {
       window.removeEventListener('mouseup', onEnd);
       window.removeEventListener('mousemove', onDrag);
+      windowListenersRef.current = null;
       setDragging('none');
       resize(`${targetRef.current!.clientWidth}px`, `${targetRef.current!.clientHeight}px`);
       dragStart.current = undefined;
     };

     const onStart = (e: MouseEvent) => {
       e.preventDefault();
       window.addEventListener('mouseup', onEnd);
       window.addEventListener('mousemove', onDrag);
+      windowListenersRef.current = {
+        cleanup: () => {
+          window.removeEventListener('mouseup', onEnd);
+          window.removeEventListener('mousemove', onDrag);
+        },
+      };
       dragSide.current = (e.currentTarget as HTMLElement).dataset.side as DragSide;
       dragStart.current = [
         (targetRef.current?.clientWidth ?? 0) - e.clientX,
         (targetRef.current?.clientHeight ?? 0) - e.clientY,
       ];
       setDragging(dragSide.current);
     };

     const handles = [dragRefX.current, dragRefY.current, dragRefXY.current];
     handles.forEach((el) => el?.addEventListener('mousedown', onStart));
-    return () => handles.forEach((el) => el?.removeEventListener('mousedown', onStart));
+    return () => {
+      handles.forEach((el) => el?.removeEventListener('mousedown', onStart));
+      windowListenersRef.current?.cleanup();
+    };
   }, [resize]);
```

</details>

